"""Self-contained matched-comparison evidence report with guard/memory separation."""
from html import escape
from .agent_benchmark import VARIANTS
from .execution_benchmark import MODES

LABELS = {"no_memory": "Geen geheugen", "unvalidated_memory": "Ongetoetst geheugen", "validated_memory": "Getoetst geheugen",
          "guard_off": "Zonder extra schrijfcontrole", "guard_on": "Met schrijfcontrole"}


def render_execution(report, rollouts):
    table_rows = ""
    for mode in MODES:
        for variant in VARIANTS:
            cell = report["results"]["conditions"][f"{mode}/{variant}"]
            table_rows += f'<tr><td>{LABELS[mode]}</td><td>{LABELS[variant]}</td><td>{cell["successful"]}/{cell["total"]}</td><td>{cell["clean_completion"]}/{cell["total"]}</td><td class="{ "bad" if cell["wrong_write_commits"] else "ok" }">{cell["wrong_write_commits"]}</td><td>{cell["blocked_writes"]}</td><td>{cell["unsafe_write_attempts"]}</td><td>{cell["model_calls"]}</td></tr>'
    cost_rows = ""
    for mode in MODES:
        for variant in VARIANTS:
            cell = report["results"]["conditions"][f"{mode}/{variant}"]
            cost_rows += f'<tr><td>{LABELS[mode]}</td><td>{LABELS[variant]}</td><td>{cell["input_tokens"]}</td><td>{cell["output_tokens"]}</td><td>{cell["tool_calls"]}</td><td>{cell["calibration_reads"]}</td><td>{cell["exact_derivations"]}</td><td>{cell["wall_seconds"]:.2f} s</td></tr>'
    task_rows = ""
    index = {(row["trial"], row["case_id"], row["mode"], row["variant"]): row for row in rollouts}
    for trial, case_id in sorted({(row["trial"], row["case_id"]) for row in rollouts}):
        selected = [index[trial, case_id, mode, variant] for mode in MODES for variant in VARIANTS]
        changed = len({(row["grade"]["passed"], row["grade"]["wrong_write_commits"]) for row in selected}) > 1
        cells = "".join(f'<td class="{ "ok" if row["grade"]["passed"] else "bad" }">{"Geslaagd" if row["grade"]["passed"] else "Mislukt"}<small>{row["grade"]["wrong_write_commits"]} fout opgeslagen · {row["grade"]["unsafe_write_attempts"]} onveilige pogingen</small></td>' for row in selected)
        task_rows += f'<tr data-different="{str(changed).lower()}"><td>{trial+1} / {escape(case_id)}<small>{escape(selected[0]["category"])}</small></td>{cells}</tr>'
    limits = "".join(f"<li>{escape(item)}</li>" for item in report["limitations"])
    total_wrong = sum(cell["wrong_write_commits"] for key, cell in report["results"]["conditions"].items() if key.startswith("guard_on/"))
    return f'''<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Experience Forge 0.3 — rekenen, schrijven en leren</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#f2f4ee;color:#20372c;font:16px/1.55 system-ui,sans-serif}}main{{max-width:1250px;margin:auto;padding:30px 22px 65px}}header{{display:flex;justify-content:space-between;gap:15px;border-bottom:1px solid #d3ded1;padding-bottom:18px}}header strong{{font-size:23px}}.badge{{font-size:12px;background:#dfeade;border-radius:20px;padding:6px 12px}}h1{{font-size:clamp(32px,5vw,56px);line-height:1.1;letter-spacing:-.04em;max-width:920px}}.intro{{font-size:19px;color:#607365;max-width:840px}}.cards{{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:30px 0}}article{{border:1px solid #d3ded1;background:white;border-radius:10px;padding:22px}}article strong{{display:block;font-size:38px}}article p{{margin:7px 0;color:#607365}}h2{{font-size:25px;margin:35px 0 15px}}.notice{{background:#e6eee1;border-left:4px solid #538263;padding:18px}}.table{{overflow-x:auto;border:1px solid #d3ded1;border-radius:10px;background:white}}table{{border-collapse:collapse;width:100%;font-size:13px}}th,td{{padding:12px 13px;border-bottom:1px solid #ebf0e8;text-align:left;vertical-align:top}}th{{background:#e6eee1;white-space:nowrap}}td{{min-width:100px}}small{{display:block;color:#6e7c71;font-size:11px;margin-top:4px}}.ok{{color:#276946}}.bad{{color:#a3452d}}button{{font:inherit;font-size:13px;background:#286246;color:white;border:0;border-radius:7px;padding:10px 15px;cursor:pointer;margin-bottom:12px}}button:focus-visible,summary:focus-visible{{outline:3px solid #b06a23;outline-offset:3px}}details{{margin-top:25px;padding:18px;border:1px solid #d3ded1;border-radius:10px}}summary{{cursor:pointer;font-weight:650}}li{{margin:10px 0}}footer{{font-size:12px;color:#68796c;margin-top:30px;overflow-wrap:anywhere}}@media(max-width:700px){{main{{padding:22px 15px}}.cards{{grid-template-columns:1fr}}h1{{font-size:36px}}header{{align-items:flex-start}}}}</style></head><body><main>
<header><strong>Experience Forge / 0.3</strong><span class="badge">Echte lokale modelruns · geen betaalde API</span></header>
<h1>Geheugen helpt leren.<br>Schrijfcontrole bewaakt de uitvoering.</h1><p class="intro">Een nieuwe proef vergelijkt drie geheugenvarianten telkens met én zonder extra controle vóór opslaan. De rekentool is in alle zes condities gelijk. Zo blijven geheugen en uitvoeringscontrole afzonderlijk zichtbaar.</p>
<div class="cards"><article><strong>{report["protocol"]["trials"]} datasets</strong><p>{len(rollouts)} echte eindtest-runs, verdeeld over zes gematchte condities.</p></article><article><strong>{total_wrong}</strong><p>Verkeerde waarden daadwerkelijk opgeslagen met schrijfcontrole.</p></article><article><strong>{report["reference"]["successful"]}/{report["reference"]["total"]}</strong><p>Deterministische referentiecontrole. Dit is code, geen AI-prestatie.</p></article></div>
<div class="notice">Een geblokkeerde fout is geen bewijs dat het model beter heeft geleerd. Daarom rapporteren we voltooiing, onveilige pogingen en werkelijk verkeerde schrijfacties apart. De kleine, ontworpen taakfamilie ondersteunt geen algemene intelligentieclaim.</div>
<h2>Hoofdresultaten: geheugen × schrijfcontrole</h2><p>‘Zonder onveilige poging’ vereist zowel juiste voltooiing als nul onveilige schrijfpogingen. Een geblokkeerde poging kan gevolgd worden door herstel; de poging blijft zichtbaar.</p><div class="table"><table><thead><tr><th>Uitvoering</th><th>Geheugen</th><th>Voltooid</th><th>Zonder onveilige poging</th><th>Fout opgeslagen</th><th>Geblokkeerd</th><th>Onveilige pogingen</th><th>Modelaanroepen</th></tr></thead><tbody>{table_rows}</tbody></table></div>
<h2>Wat de code controleert</h2><p>De rekentool leidt coëfficiënten af met exacte breuken en controleert alle kalibratievoorbeelden. De schrijfcontrole accepteert alleen het resultaat van de laatste ondersteunde berekening, gebonden aan bron, versie, invoer en kalibratie. Nieuwe mislukte berekeningen maken een eerder bewijs ongeldig. Deze checks gebruiken beschikbare toolgegevens; de verborgen beoordelingslabels worden niet gebruikt.</p>
<h2>Verbruik en snelheid</h2><p>Onderstaande cijfers zijn uitsluitend de eindtest. Gedeelde training en voorstellen: {report["shared_learning"]["model_calls"]} modelaanroepen, {report["shared_learning"]["input_tokens"]} invoertokens en {report["shared_learning"]["output_tokens"]} uitvoertokens, gelijk toegerekend aan iedere conditie en fysiek één keer uitgevoerd. Kwalificatie gebruikt geen modelaanroepen. Kalibratiechecks en schrijfcontrole kosten daarnaast CPU-tijd; die tijd zit in de gemeten duur per taak.</p><div class="table"><table><thead><tr><th>Uitvoering</th><th>Geheugen</th><th>Invoertokens</th><th>Uitvoertokens</th><th>Toolacties</th><th>Kalibraties</th><th>Exact afgeleid</th><th>Tijd</th></tr></thead><tbody>{cost_rows}</tbody></table></div>
<h2>Alle eindtaken</h2><button id="filter" type="button" aria-pressed="false">Toon alleen verschillen</button><div class="table"><table><thead><tr><th>Dataset / taak</th><th>Zonder controle<br>Geen geheugen</th><th>Zonder controle<br>Ongetoetst</th><th>Zonder controle<br>Getoetst</th><th>Met controle<br>Geen geheugen</th><th>Met controle<br>Ongetoetst</th><th>Met controle<br>Getoetst</th></tr></thead><tbody>{task_rows}</tbody></table></div>
<details open><summary>Grenzen van deze proef</summary><ul>{limits}</ul><p>Alle modelverzoeken, toolacties, kalibratieregels, eindtoestanden en beoordelingsbesluiten staan in het bewijspakket. Offline replay controleert de vastgelegde beslissingen zonder nieuwe modelaanroepen.</p></details>
<footer>Model: {escape(report["runtime"]["model"]["name"])} · SHA-256: {escape(report["runtime"]["model"]["digest"])}<br>Werkelijk uitgevoerde modelaanroepen: {report["total_actual_model_calls"]} · Betaalde API-aanroepen: {report["paid_api_calls"]} · Externe providerverzoeken: {report["remote_network_requests"]}</footer>
</main><script>const button=document.getElementById('filter');button.addEventListener('click',()=>{{const selected=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(selected));button.textContent=selected?'Toon alle taken':'Toon alleen verschillen';document.querySelectorAll('tbody tr').forEach(row=>row.hidden=selected&&row.dataset.different!=='true');}});</script></body></html>'''
